// Code node: "Preparar mensagem"
// Modo: Run Once for Each Item
// Achata o payload do Chatwoot no que o resto do fluxo usa e classifica o tipo da mensagem.
// Só o tipo "texto" vai para a IA; os outros recebem resposta fixa (economiza chamada e evita 429).
//
// tipo:
//   texto          -> tem texto útil (digitado, legenda de mídia ou áudio transcrito pelo Chatwoot)
//   vazio          -> só espaço, pontuação ou emoji
//   midia          -> foto, vídeo, figurinha, documento... sem legenda
//   audio          -> áudio sem transcrição
//   nao_suportado  -> o WhatsApp não entregou o conteúdo (ex.: visualização única)

const body = $json.body ?? {};
const anexos = Array.isArray(body.attachments) ? body.attachments : [];

// Limpa o que o contato digitou: junta espaços e reduz pontuação repetida ("oi......" -> "oi.").
function limparTexto(valor) {
  return String(valor ?? '')
    .replace(/\s+/g, ' ')
    .replace(/([.,;:!?])\1+/g, '$1')
    .replace(/^[\s.,;:!?]+/, '')
    .trim();
}

// Texto útil = tem pelo menos uma letra ou número (emoji e pontuação sozinhos não contam).
const temConteudo = texto => /[\p{L}\p{N}]/u.test(texto);

const textoDigitado = limparTexto(body.content);
const audio = anexos.find(a => a.file_type === 'audio');
const textoAudio = limparTexto(audio?.transcribed_text);

let tipo;
let texto = '';
let origem = null;

if (body.content_attributes?.is_unsupported) {
  tipo = 'nao_suportado';
} else if (temConteudo(textoDigitado)) {
  tipo = 'texto';
  texto = textoDigitado;
  origem = anexos.length ? 'legenda' : 'digitado';
} else if (audio && temConteudo(textoAudio)) {
  tipo = 'texto';
  texto = textoAudio;
  origem = 'audio_transcrito';
} else if (audio) {
  tipo = 'audio';
} else if (anexos.length || body.content_type === 'sticker') {
  tipo = 'midia';
} else {
  tipo = 'vazio';
}

// Figurinha: o Chatwoot marca content_type "sticker"; no WhatsApp ela também chega como imagem .webp.
const eh_figurinha = body.content_type === 'sticker' ||
  anexos.some(a => a.file_type === 'image' && String(a.extension ?? '').toLowerCase() === 'webp');

return {
  json: {
    eh_figurinha: tipo === 'midia' && eh_figurinha,
    message_id: body.id,
    account_id: body.account?.id,
    conversation_id: body.conversation?.id,
    contato_nome: body.sender?.name ?? null,
    telefone: body.sender?.phone_number ?? body.conversation?.meta?.sender?.phone_number ?? null,
    created_at: body.created_at,
    tipo,
    texto,
    origem,
    config: $json.config,
  },
};

// Code node: "Normalizar telefone (2.1)"
// Modo: Run Once for Each Item
// Entrada: $json.telefone (qualquer formato). Saída: o mesmo item + telefone_normalizado
// no formato +55DDDNÚMERO, ou null quando não dá para garantir um celular brasileiro válido.

// DDDs em uso no Brasil (Anatel). Combinações como 20, 23, 25, 26, 30, 36... não existem.
const DDDS_VALIDOS = new Set([
  11, 12, 13, 14, 15, 16, 17, 18, 19,
  21, 22, 24, 27, 28,
  31, 32, 33, 34, 35, 37, 38,
  41, 42, 43, 44, 45, 46, 47, 48, 49,
  51, 53, 54, 55,
  61, 62, 63, 64, 65, 66, 67, 68, 69,
  71, 73, 74, 75, 77, 79,
  81, 82, 83, 84, 85, 86, 87, 88, 89,
  91, 92, 93, 94, 95, 96, 97, 98, 99,
]);

function normalizarTelefone(valor) {
  if (valor === null || valor === undefined) return null;
  const texto = String(valor).trim();
  let digitos = texto.replace(/\D/g, '');

  // Veio com "+" mas não é +55: número estrangeiro, não é celular brasileiro.
  if (texto.startsWith('+') && !digitos.startsWith('55')) return null;

  // Com código do país: 55 + DDD(2) + 9 dígitos = 13.
  // Só removemos o 55 quando o tamanho bate, porque 55 também é um DDD (RS).
  if (digitos.length === 13 && digitos.startsWith('55')) {
    digitos = digitos.slice(2);
  } else if (digitos.length === 12 && digitos.startsWith('0')) {
    // Prefixo de discagem interurbana: 0 + DDD + número.
    digitos = digitos.slice(1);
  }

  // Celular nacional: DDD(2) + 9 + 8 dígitos = 11.
  if (digitos.length !== 11) return null;
  if (!DDDS_VALIDOS.has(Number(digitos.slice(0, 2)))) return null;
  if (digitos[2] !== '9') return null;

  return '+55' + digitos;
}

return {
  json: {
    ...$json,
    telefone_normalizado: normalizarTelefone($json.telefone),
  },
};

// Junta a mensagem preparada com o estado salvo da conversa (null se é a primeira vez).
const msg = $('Normalizar telefone (2.1)').item.json;
const estado = $json.conversation_id ? $json : null;

return { json: { ...msg, estado } };

// Code node: "Montar pedido para a IA"
// Modo: Run Once for Each Item
// Monta o corpo da chamada à OpenAI. A resposta vem em JSON com schema fixo (structured output):
// a intenção só pode ser um dos 4 valores e nome/e-mail/curso vêm null quando não aparecem.

// O modelo é escolhido no nó Config (config.openai_model).
const MODELO = $json.config?.openai_model || 'gpt-4.1-nano';
// Modelos de raciocínio (gpt-5*, o1, o3...) não aceitam temperature; os demais usam 0 (resposta estável).
const ACEITA_TEMPERATURA = !/^(gpt-5|o\d)/.test(MODELO);

const INSTRUCOES = `Você classifica mensagens de WhatsApp recebidas pela Escola Fale Bem, que vende cursos de inglês e espanhol.

Escolha UMA intenção:
- interesse_matricula: quer se matricular, se inscrever, começar um curso, OU está respondendo dados pedidos para a matrícula (nome, e-mail, curso).
- duvida: pergunta sobre preço, mensalidade, matrícula, duração, turmas, horários, aula experimental ou qualquer informação sobre a escola.
- falar_com_humano: pede para falar com uma pessoa, atendente ou humano.
- outro: saudação sozinha, agradecimento, assunto sem relação com a escola, ou não dá para saber.

Extraia também, SOMENTE se estiverem escritos na mensagem:
- nome: o nome que a pessoa disse ser o dela; senão null.
- email: o endereço de e-mail escrito; senão null.
- curso: "Inglês" se a mensagem cita inglês (ou english); "Espanhol" se cita espanhol (ou spanish); "nenhum" se não cita nenhum dos dois.
Nunca invente dados.`;

const estado = $json.estado;
let contexto = 'Contexto: conversa sem matrícula em andamento.';
if (estado?.stage === 'coletando') {
  contexto = `Contexto: o bot está coletando dados de matrícula e acabou de pedir: ${estado.campo_pendente ?? 'dados'}. ` +
    `Já coletado: nome=${estado.nome ?? 'falta'}, e-mail=${estado.email ?? 'falta'}, curso=${estado.curso ?? 'falta'}. ` +
    'Se a mensagem responde a esse pedido, a intenção é interesse_matricula.';
}
// O "sim" depois de o bot oferecer atendente é tratado em código (Validar resposta da IA), não aqui:
// avisar o modelo fazia o gpt-4.1-nano classificar qualquer mensagem seguinte (até um e-mail) como falar_com_humano.

const pedido = {
  model: MODELO,
  ...(ACEITA_TEMPERATURA && { temperature: 0 }),
  messages: [
    { role: 'system', content: INSTRUCOES },
    { role: 'system', content: contexto },
    { role: 'user', content: $json.texto },
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'classificacao',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['intencao', 'nome', 'email', 'curso'],
        properties: {
          intencao: { type: 'string', enum: ['interesse_matricula', 'duvida', 'falar_com_humano', 'outro'] },
          nome: { type: ['string', 'null'] },
          email: { type: ['string', 'null'] },
          curso: { type: 'string', enum: ['Inglês', 'Espanhol', 'nenhum'] },
        },
      },
    },
  },
};

return { json: { ...$json, pedido_ia: pedido } };

// Code node: "Validar resposta da IA"
// Modo: Run Once for Each Item
// Requisito 3: se a IA falhar ou devolver algo fora da lista, a intenção vira "outro".
// A falha fica registrada em ia.erro para o bloco de falhas gravar no error_log.

const INTENCOES = ['interesse_matricula', 'duvida', 'falar_com_humano', 'outro'];
const contexto = $('Montar pedido para a IA').item.json;
const { pedido_ia, ...msg } = contexto;

function lerResposta(resposta) {
  if (resposta.error) {
    return { erro: `OpenAI: ${resposta.error.message ?? JSON.stringify(resposta.error)}` };
  }
  const conteudo = resposta.choices?.[0]?.message?.content;
  try {
    return { dados: JSON.parse(conteudo) };
  } catch {
    return { erro: `Resposta da IA não é JSON: ${String(conteudo).slice(0, 200)}` };
  }
}

const textoOuNull = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 120) : null);
const emailValido = v => (typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()) ? v.trim().toLowerCase() : null);
const cursoValido = v => (v === 'Inglês' || v === 'Espanhol' ? v : null);

// Rede de segurança para modelos pequenos: e-mail e curso dá para achar no texto sem IA.
const texto = msg.texto ?? '';
const emailNoTexto = texto.match(/[^\s@]+@[^\s@]+\.[^\s@]{2,}/)?.[0]?.replace(/[.,;!?)]+$/, '');
function cursoNoTexto() {
  const ingles = /ingl[eê]s|english/i.test(texto);
  const espanhol = /espanhol|spanish/i.test(texto);
  if (ingles === espanhol) return null; // nenhum ou os dois: não dá para decidir
  return ingles ? 'Inglês' : 'Espanhol';
}

const { dados = {}, erro = null } = lerResposta($json);

let intencao = INTENCOES.includes(dados.intencao) ? dados.intencao : 'outro';
const extraido = {
  nome: textoOuNull(dados.nome),
  email: emailValido(dados.email) ?? emailValido(emailNoTexto),
  curso: cursoNoTexto() ?? cursoValido(dados.curso), // texto sem ambiguidade vence a IA
};

// Rede de segurança: no meio da matrícula, uma resposta curta ("Mariana") que trouxe dado
// continua sendo matrícula, mesmo que a IA tenha classificado como "outro".
const trouxeDado = extraido.nome || extraido.email || extraido.curso;
if (msg.estado?.stage === 'coletando' && intencao === 'outro' && trouxeDado) {
  intencao = 'interesse_matricula';
}

// Rede de segurança: o bot ofereceu atendente há pouco e a resposta é um "sim" curto.
const ofereceuHaPouco = msg.estado?.ofereceu_atendente_em &&
  Date.now() - Date.parse(msg.estado.ofereceu_atendente_em) < 30 * 60 * 1000;
const respostaAfirmativa = /^(sim|s|quero|pode|pode ser|claro|ok|por favor|isso)\b/i.test(texto.trim());
if (ofereceuHaPouco && intencao === 'outro' && respostaAfirmativa) {
  intencao = 'falar_com_humano';
}

return {
  json: {
    ...msg,
    ia: {
      intencao,
      ...extraido,
      erro: erro ?? (dados.intencao && !INTENCOES.includes(dados.intencao) ? `Intenção fora da lista: ${dados.intencao}` : null),
    },
  },
};

// Code node: "Montar aviso (mensagem sem texto)"
// Modo: Run Once for Each Item
// "?", "......", emoji solto, foto/documento sem legenda, áudio sem transcrição, visualização única, figurinha.
// Nada disso vai para a IA. Quem manda várias seguidas está com dificuldade, então o bot escala:
//   1ª -> aviso   2ª -> oferece atendente   3ª -> transfere (faixa humano)   4ª+ -> silêncio
// Figurinha é exceção (rajada de figurinhas é brincadeira, não pedido de ajuda): só o 1º aviso.
// "Seguidas" = dentro de 10 minutos do último aviso. No meio da matrícula, o aviso lembra o dado que falta.

const JANELA = 10 * 60 * 1000;

const estado = $json.estado ?? {};
const tipo = $json.tipo;
const recente = estado.ultimo_aviso_em && Date.now() - Date.parse(estado.ultimo_aviso_em) < JANELA;
const qtd_sem_texto = recente ? (estado.qtd_sem_texto ?? 0) + 1 : 1;

const LEMBRETES = {
  nome: 'Para continuar sua pré-matrícula, qual é o seu nome completo?',
  email: 'Para continuar sua pré-matrícula, qual é o seu e-mail?',
  curso: 'Para continuar sua pré-matrícula, qual curso te interessa: Inglês ou Espanhol?',
};
const lembrete = estado.stage === 'coletando' ? LEMBRETES[estado.campo_pendente] ?? '' : '';
const comLembrete = texto => (lembrete ? `${texto} ${lembrete}` : texto);

const PRIMEIRO_AVISO = {
  audio: comLembrete('Ainda não consigo ouvir áudios. Pode me escrever o que você precisa?'),
  midia: comLembrete('Ainda não consigo ver imagens, vídeos ou figurinhas. Pode me escrever o que você precisa?'),
  nao_suportado: comLembrete('Não consegui abrir essa mensagem (mensagens de visualização única não chegam para mim). Pode me escrever o que você precisa?'),
  vazio: lembrete
    ? `Não entendi sua mensagem. ${lembrete}`
    : 'Não entendi sua mensagem. Posso te ajudar com informações sobre cursos e preços, fazer sua pré-matrícula ou chamar uma atendente. O que você precisa?',
};

// acao: avisar | transferir | silenciar
let acao = 'silenciar';
let resposta = null;
let ofereceu_atendente = false;

if (qtd_sem_texto === 1) {
  acao = 'avisar';
  resposta = PRIMEIRO_AVISO[tipo] ?? PRIMEIRO_AVISO.vazio;
} else if ($json.eh_figurinha) {
  acao = 'silenciar';
} else if (qtd_sem_texto === 2) {
  acao = 'avisar';
  ofereceu_atendente = true;
  resposta = tipo === 'audio'
    ? 'Ainda não consigo ouvir áudios. Se preferir, posso te passar para uma atendente. Quer?'
    : 'Parece que não estou conseguindo te entender por aqui. Quer que eu chame uma atendente?';
} else if (qtd_sem_texto === 3) {
  acao = 'transferir';
}

return {
  json: { ...$json, acao_sem_texto: acao, resposta, ultimo_aviso: tipo, qtd_sem_texto, ofereceu_atendente },
};

// Code node: "Montar pedido de resposta (dúvida)"
// Modo: Run Once for Each Item
// Requisito 4: responder SOMENTE com os dados do cenário. Sem resposta ali -> diz que não sabe
// e oferece uma atendente. A trava contra preço/horário inventado fica no nó seguinte.

const MODELO = $json.config?.openai_model || 'gpt-4.1-nano';
const ACEITA_TEMPERATURA = !/^(gpt-5|o\d)/.test(MODELO);

const DADOS_DA_ESCOLA = `Escola Fale Bem — dados oficiais (única fonte permitida):
- Inglês: duração de 18 meses, mensalidade de R$ 389, turmas de manhã, à noite e aos sábados.
- Espanhol: duração de 12 meses, mensalidade de R$ 349, turmas à noite e aos sábados.
- Matrícula: R$ 120.
- Aula experimental: gratuita.
- Atendimento humano: de segunda a sexta, das 8h às 18h, horário de Recife.`;

const INSTRUCOES = `Você é o assistente de WhatsApp da Escola Fale Bem. Responda à dúvida do contato em português, de forma curta e simpática (no máximo 3 frases).

Regras obrigatórias:
1. Use SOMENTE os dados oficiais abaixo. Não use conhecimento próprio.
2. Nunca invente preço, desconto, forma de pagamento, horário de aula, endereço, professor ou qualquer dado que não esteja abaixo.
3. Se a pergunta não puder ser respondida só com esses dados, diga que não tem essa informação e pergunte se a pessoa quer falar com uma atendente. Nesse caso, marque respondida_com_dados = false.

${DADOS_DA_ESCOLA}`;

const pedido = {
  model: MODELO,
  ...(ACEITA_TEMPERATURA && { temperature: 0 }),
  messages: [
    { role: 'system', content: INSTRUCOES },
    { role: 'user', content: $json.texto },
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'resposta_duvida',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['resposta', 'respondida_com_dados'],
        properties: {
          resposta: { type: 'string' },
          respondida_com_dados: { type: 'boolean' },
        },
      },
    },
  },
};

return { json: { ...$json, pedido_ia: pedido } };

// Code node: "Conferir resposta da dúvida"
// Modo: Run Once for Each Item
// Trava contra invenção: toda quantia em R$ e todo horário citado precisam existir nos dados oficiais.
// Se a IA falhou ou citou algo fora da lista, a resposta é trocada por uma mensagem segura.

const PRECOS_OFICIAIS = new Set([389, 349, 120]);
const HORAS_OFICIAIS = new Set([8, 18]);

const SEM_RESPOSTA = 'Essa informação eu não tenho aqui. Quer que eu chame uma atendente para te ajudar?';
const CONTINGENCIA = 'Desculpe, tive um problema para responder agora. Já deixei sua mensagem registrada e uma atendente vai te responder assim que possível.';

const contexto = $('Montar pedido de resposta (dúvida)').item.json;
const { pedido_ia, ...msg } = contexto;
const erros = [msg.ia?.erro].filter(Boolean);

function lerResposta(resposta) {
  if (resposta.error) return { erro: `OpenAI (dúvida): ${resposta.error.message ?? JSON.stringify(resposta.error)}` };
  try {
    const dados = JSON.parse(resposta.choices?.[0]?.message?.content);
    if (typeof dados.resposta !== 'string' || !dados.resposta.trim()) throw new Error('vazia');
    return { dados };
  } catch {
    return { erro: 'Resposta da dúvida inválida' };
  }
}

// Lista o que a resposta afirma que não está nos dados oficiais.
function dadosInventados(texto) {
  const problemas = [];
  for (const [, valor] of texto.matchAll(/R\$\s*(\d+(?:[.,]\d+)?)/g)) {
    const numero = Number(valor.replace(/\.(?=\d{3})/g, '').replace(',', '.'));
    if (!PRECOS_OFICIAIS.has(numero)) problemas.push(`preço R$ ${valor}`);
  }
  for (const [, hora] of texto.matchAll(/\b(\d{1,2})\s*(?:h|horas?\b|:\d{2})/gi)) {
    if (!HORAS_OFICIAIS.has(Number(hora))) problemas.push(`horário ${hora}h`);
  }
  return problemas;
}

const { dados, erro } = lerResposta($json);
let resposta;
let trava = null;

if (erro) {
  erros.push(erro);
  resposta = CONTINGENCIA;
} else {
  const inventado = dadosInventados(dados.resposta);
  if (inventado.length) {
    trava = `Resposta descartada, citava ${inventado.join(', ')}: "${dados.resposta}"`;
    resposta = SEM_RESPOSTA;
  } else {
    resposta = dados.resposta.trim();
  }
}

return {
  json: {
    ...msg,
    resposta,
    oferece_atendente: Boolean(trava) || dados?.respondida_com_dados === false,
    trava_anti_invencao: trava,
    erros,
  },
};

// Code node: "Atualizar dados do lead"
// Modo: Run Once for Each Item
// Requisito 5: junta o que já foi coletado (Postgres) com o que a IA extraiu desta mensagem
// e decide o próximo passo:
//   perguntar  -> ainda falta nome, e-mail ou curso (pergunta um por vez, nessa ordem)
//   cadastrar  -> tem os três: segue para o Pipedrive
// Quem já virou lead (stage "concluido") também passa pelo Pipedrive: o cadastro não duplica
// pessoa nem negócio aberto, e se alguém apagou o lead no CRM, ele é recriado.

// Dados do cenário (PDF). O valor do negócio no Pipedrive é a previsão do contrato:
// matrícula + mensalidade × duração. A atendente ajusta se houver desconto.
const MATRICULA = 120;
const CURSOS = {
  'Inglês': { mensalidade: 389, meses: 18 },
  'Espanhol': { mensalidade: 349, meses: 12 },
};
const valorContrato = curso => (CURSOS[curso] ? MATRICULA + CURSOS[curso].mensalidade * CURSOS[curso].meses : null);

const estado = $json.estado ?? {};
const ia = $json.ia ?? {};

// Dado novo desta mensagem vale mais que o salvo (permite corrigir o e-mail, por exemplo).
const lead = {
  nome: ia.nome ?? estado.nome ?? null,
  email: ia.email ?? estado.email ?? null,
  curso: ia.curso ?? estado.curso ?? null,
};
const primeiroNome = lead.nome ? lead.nome.split(' ')[0] : '';
const perguntouAntes = campo => estado.stage === 'coletando' && estado.campo_pendente === campo;

function pergunta(campo) {
  if (campo === 'nome') {
    return perguntouAntes('nome')
      ? 'Não consegui pegar seu nome. Pode me dizer como você se chama?'
      : 'Que ótimo que você quer estudar com a gente! Para fazer sua pré-matrícula, qual é o seu nome completo?';
  }
  if (campo === 'email') {
    if (perguntouAntes('email')) {
      return $json.texto.includes('@')
        ? 'Esse e-mail parece incompleto. Pode conferir e mandar de novo? (ex.: nome@gmail.com)'
        : 'Qual é o seu e-mail? (ex.: nome@gmail.com)';
    }
    return ia.nome && !estado.nome ? `Prazer, ${primeiroNome}! Qual é o seu e-mail?` : 'Qual é o seu e-mail?';
  }
  return perguntouAntes('curso')
    ? 'Temos Inglês e Espanhol. Qual dos dois você prefere?'
    : 'E qual curso te interessa: Inglês ou Espanhol?';
}

let acao;
let resposta = null;
let campo_pendente = null;
let novo_stage;

const ja_era_lead = estado.stage === 'concluido';
const faltando = ['nome', 'email', 'curso'].filter(campo => !lead[campo]);

if (faltando.length) {
  acao = 'perguntar';
  novo_stage = 'coletando';
  campo_pendente = faltando[0];
  resposta = pergunta(campo_pendente);
} else {
  acao = 'cadastrar';
  // Só vira (ou continua) "concluido" depois que o Pipedrive confirmar.
  novo_stage = ja_era_lead ? 'concluido' : 'coletando';
}

return {
  json: {
    ...$json,
    lead: { ...lead, valor_contrato: valorContrato(lead.curso) },
    ja_era_lead,
    acao,
    campo_pendente,
    novo_stage,
    resposta,
  },
};

// Code node: "Encontrar pessoa pelo telefone"
// Modo: Run Once for Each Item
// Requisito 5 (sem duplicar pelo telefone) e Parte 3, caso 2.
// A busca do Pipedrive é por trecho do telefone, então pode trazer gente parecida.
// Aqui cada telefone encontrado é normalizado (mesma função do 2.1) e só conta
// como a mesma pessoa se ficar idêntico ao telefone do contato.

// DDDs em uso no Brasil (Anatel). Combinações como 20, 23, 25, 26, 30, 36... não existem.
const DDDS_VALIDOS = new Set([
  11, 12, 13, 14, 15, 16, 17, 18, 19,
  21, 22, 24, 27, 28,
  31, 32, 33, 34, 35, 37, 38,
  41, 42, 43, 44, 45, 46, 47, 48, 49,
  51, 53, 54, 55,
  61, 62, 63, 64, 65, 66, 67, 68, 69,
  71, 73, 74, 75, 77, 79,
  81, 82, 83, 84, 85, 86, 87, 88, 89,
  91, 92, 93, 94, 95, 96, 97, 98, 99,
]);

function normalizarTelefone(valor) {
  if (valor === null || valor === undefined) return null;
  const texto = String(valor).trim();
  let digitos = texto.replace(/\D/g, '');

  // Veio com "+" mas não é +55: número estrangeiro, não é celular brasileiro.
  if (texto.startsWith('+') && !digitos.startsWith('55')) return null;

  // Com código do país: 55 + DDD(2) + 9 dígitos = 13.
  // Só removemos o 55 quando o tamanho bate, porque 55 também é um DDD (RS).
  if (digitos.length === 13 && digitos.startsWith('55')) {
    digitos = digitos.slice(2);
  } else if (digitos.length === 12 && digitos.startsWith('0')) {
    // Prefixo de discagem interurbana: 0 + DDD + número.
    digitos = digitos.slice(1);
  }

  // Celular nacional: DDD(2) + 9 + 8 dígitos = 11.
  if (digitos.length !== 11) return null;
  if (!DDDS_VALIDOS.has(Number(digitos.slice(0, 2)))) return null;
  if (digitos[2] !== '9') return null;

  return '+55' + digitos;
}

const contexto = $('Atualizar dados do lead').item.json;
const alvo = contexto.telefone_normalizado;
const resultados = $json.data?.items ?? [];

let pessoa = null;
if (alvo) {
  for (const { item } of resultados) {
    const telefones = (item?.phones ?? []).map(t => (typeof t === 'string' ? t : t?.value));
    if (telefones.some(t => normalizarTelefone(t) === alvo)) {
      pessoa = item;
      break;
    }
  }
}

return {
  json: {
    ...contexto,
    pipedrive_person_id: pessoa?.id ?? null,
  },
};

// Atualizar ou criar: os dois devolvem a pessoa em data.id. Guarda junto com o contexto do lead.
const contexto = $('Encontrar pessoa pelo telefone').item.json;

return { json: { ...contexto, pipedrive_person_id: $json.data.id } };

// Code node: "Verificar negócio aberto"
// Modo: Run Once for Each Item
// Lead que volta numa conversa nova não gera negócio repetido: se a pessoa já tem um negócio
// ABERTO com o mesmo título, reaproveitamos. Ganho ou perdido não conta (aí é uma nova venda).

const contexto = $('Guardar id da pessoa').item.json;
const titulo = `Matrícula ${contexto.lead.curso}`;
const negocios = Array.isArray($json.data) ? $json.data : [];
const aberto = negocios.find(n => n.title === titulo && n.status === 'open');

return {
  json: {
    ...contexto,
    titulo_negocio: titulo,
    negocio_existente_id: aberto?.id ?? null,
  },
};

// Code node: "Confirmar matrícula"
// Modo: Run Once for Each Item
// Pipedrive e etiqueta deram certo: marca a conversa como concluída e monta a confirmação.
// Quem já era lead recebe um "seus dados já estão com a equipe" em vez da confirmação nova.

const contexto = $('Atualizar dados do lead').item.json;
const primeiroNome = contexto.lead.nome.split(' ')[0];

const resposta = contexto.ja_era_lead
  ? `Seus dados já estão com a nossa equipe, ${primeiroNome}! Uma atendente vai falar com você para finalizar ` +
    'a matrícula. Se quiser falar com ela agora, é só pedir.'
  : `Prontinho, ${primeiroNome}! Sua pré-matrícula no curso de ${contexto.lead.curso} foi registrada. ` +
    'Uma atendente vai entrar em contato para finalizar. Ah, e a aula experimental é gratuita!';

return {
  json: {
    ...contexto,
    novo_stage: 'concluido',
    campo_pendente: null,
    resposta,
  },
};

// Code node: "Horário de atendimento (com feriados)"
// Modo: Run Once for Each Item
// Requisito 6. Mesma regra do exercício 2.2 (seg-sex, 8h-18h, America/Recife) + feriados do nó
// "Config: feriados". Fora do horário, calcula quando a equipe volta, pulando fim de semana e feriado
// (ex.: sexta 09/10 às 19h -> segunda 12/10 é feriado -> volta terça, 13/10, às 8h).

const FUSO = 'America/Recife';
const ABRE = 8;   // 08:00
const FECHA = 18; // 18:00 (exclusive)
const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const feriados = new Set($json.feriados ?? []);

// Data e hora de Recife a partir de um instante (Intl é nativo do JS; continua certo se o fuso mudar de regra).
const formatador = new Intl.DateTimeFormat('en-CA', {
  timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23', weekday: 'short',
});
const SEMANA = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

function emRecife(instante) {
  const p = Object.fromEntries(formatador.formatToParts(instante).map(x => [x.type, x.value]));
  return {
    data: `${p.year}-${p.month}-${p.day}`,
    diaSemana: SEMANA[p.weekday],
    minutos: Number(p.hour) * 60 + Number(p.minute),
  };
}

const diaUtil = r => r.diaSemana >= 1 && r.diaSemana <= 5 && !feriados.has(r.data);

// Momento da mensagem (o Chatwoot pode mandar ISO ou timestamp em segundos); sem data válida, agora.
function instanteDaMensagem(valor) {
  const data = typeof valor === 'number' ? new Date(valor * 1000) : new Date(valor ?? NaN);
  return Number.isNaN(data.getTime()) ? new Date() : data;
}

const agora = instanteDaMensagem($json.created_at);
const hoje = emRecife(agora);
const dentro_do_horario = diaUtil(hoje) && hoje.minutos >= ABRE * 60 && hoje.minutos < FECHA * 60;

let motivo = null;
let proxima_abertura = null;
if (!dentro_do_horario) {
  motivo = feriados.has(hoje.data) ? 'feriado' : !diaUtil(hoje) ? 'fim_de_semana' : 'fora_do_horario';

  // Hoje ainda abre (dia útil, antes das 8h)? Senão, procura o próximo dia útil.
  let dia = hoje;
  let diasAFrente = 0;
  if (!(diaUtil(hoje) && hoje.minutos < ABRE * 60)) {
    do {
      diasAFrente += 1;
      dia = emRecife(new Date(agora.getTime() + diasAFrente * 24 * 60 * 60 * 1000));
    } while (!diaUtil(dia) && diasAFrente < 15);
  }
  const [, mes, diaMes] = dia.data.split('-');
  const quando = diasAFrente === 0 ? 'hoje' : diasAFrente === 1 ? 'amanhã' : DIAS[dia.diaSemana];
  proxima_abertura = `${quando}, ${diaMes}/${mes}, às ${ABRE}h`;
}

return {
  json: { ...$json, dentro_do_horario, motivo_fora_do_horario: motivo, proxima_abertura },
};

// Code node: "Montar resposta (outro)"
// Modo: Run Once for Each Item
// Saudação, agradecimento, assunto sem relação ou falha da IA (requisito 3: falhou -> "outro").
// No meio da matrícula, lembra o dado que falta; senão, apresenta o que o bot sabe fazer.

const estado = $json.estado ?? {};

const LEMBRETES = {
  nome: 'Para continuar sua pré-matrícula, qual é o seu nome completo?',
  email: 'Para continuar sua pré-matrícula, qual é o seu e-mail?',
  curso: 'Para continuar sua pré-matrícula, qual curso te interessa: Inglês ou Espanhol?',
};
const lembrete = estado.stage === 'coletando' ? LEMBRETES[estado.campo_pendente] : null;

const resposta = lembrete ??
  'Oi! Sou o assistente virtual da Escola Fale Bem. Posso te ajudar com informações sobre os cursos de inglês e espanhol, ' +
  'fazer sua pré-matrícula ou chamar uma atendente. Como posso ajudar?';

return { json: { ...$json, resposta } };

