const DDDS_VALIDOS = new Set([
  11, 12, 13, 14, 15, 16, 17, 18, 19,
  21, 22, 24, 27, 28,
  31, 32, 33, 34, 35, 37, 38,
  41, 42, 43, 44, 45, 46, 47, 48, 49,
  51, 53, 54, 55,
  61, 62, 63, 64, 65, 66, 67, 68, 69,
  71, 73, 74, 75, 77, 79,
  81, 82, 83, 84, 85, 86, 87, 88, 89,
  91, 92, 93, 94, 95, 96, 97, 98, 99,
]);

function normalizarTelefone(valor) {
  if (valor === null || valor === undefined) return null;
  const texto = String(valor).trim();
  let digitos = texto.replace(/\D/g, '');

  // Veio com "+" mas não é +55: número estrangeiro, não é celular brasileiro.
  if (texto.startsWith('+') && !digitos.startsWith('55')) return null;

  // Com código do país: 55 + DDD(2) + 9 dígitos = 13.
  // Só removemos o 55 quando o tamanho bate, porque 55 também é um DDD (RS).
  if (digitos.length === 13 && digitos.startsWith('55')) {
    digitos = digitos.slice(2);
  } else if (digitos.length === 12 && digitos.startsWith('0')) {
    // Prefixo de discagem interurbana: 0 + DDD + número.
    digitos = digitos.slice(1);
  }

  // Celular nacional: DDD(2) + 9 + 8 dígitos = 11.
  if (digitos.length !== 11) return null;
  if (!DDDS_VALIDOS.has(Number(digitos.slice(0, 2)))) return null;
  if (digitos[2] !== '9') return null;

  return '+55' + digitos;
}

return {
  json: {
    ...$json,
    telefone_normalizado: normalizarTelefone($json.telefone),
  },
};

// Code node: "Dentro do horário de atendimento (2.2)"
// Modo: Run Once for Each Item
// Entrada: $json.data (ISO 8601 em UTC). Saída: o mesmo item + dentro_do_horario (boolean).
// Regra: segunda a sexta, das 8h00 (inclusive) às 18h00 (exclusive), fuso America/Recife.

const FUSO = 'America/Recife';
const DIAS_UTEIS = new Set(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
const ABRE = 8 * 60;   // 08:00 em minutos
const FECHA = 18 * 60; // 18:00 em minutos

// Usa o Intl (nativo do JS) para ler dia da semana e hora no fuso de Recife,
// em vez de subtrair 3h na mão: continua certo se o fuso mudar de regra.
const formatador = new Intl.DateTimeFormat('en-US', {
  timeZone: FUSO,
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hourCycle: 'h23',
});

function dentroDoHorario(iso) {
  const data = new Date(iso);
  // Data inválida conta como fora do horário: na dúvida, não prometemos atendente.
  if (!iso || Number.isNaN(data.getTime())) return false;

  const partes = Object.fromEntries(
    formatador.formatToParts(data).map(p => [p.type, p.value]),
  );
  const minutos = Number(partes.hour) * 60 + Number(partes.minute);

  return DIAS_UTEIS.has(partes.weekday) && minutos >= ABRE && minutos < FECHA;
}

return {
  json: {
    ...$json,
    dentro_do_horario: dentroDoHorario($json.data),
  },
};

return [
  { json: { conversation_id: 42, content: 'do curso de inglês', created_at: '2026-10-05T12:00:09Z' } },
  { json: { conversation_id: 77, content: 'boa tarde', created_at: '2026-10-05T12:00:03Z' } },
  { json: { conversation_id: 42, content: 'oi', created_at: '2026-10-05T12:00:01Z' } },
  { json: { conversation_id: 42, content: 'queria saber o valor', created_at: '2026-10-05T12:00:05Z' } },
];

// Code node: "Juntar mensagens picadas (2.3)"
// Modo: Run Once for All Items
// Entrada: itens com { conversation_id, content, created_at }, em qualquer ordem.
// Saída: um item por conversa, com os textos em ordem cronológica unidos por espaço.

const conversas = new Map();

for (const [indice, item] of $input.all().entries()) {
  const { conversation_id, content, created_at } = item.json;
  const texto = String(content ?? '').trim();
  if (!texto) continue; // anexo/figurinha sem texto não entra na frase

  const quando = Date.parse(created_at);
  if (!conversas.has(conversation_id)) conversas.set(conversation_id, []);
  conversas.get(conversation_id).push({
    texto,
    created_at,
    quando: Number.isNaN(quando) ? Infinity : quando, // data inválida vai para o fim
    indice, // desempate: mesmo instante, mantém a ordem em que chegaram
  });
}

const resultado = [...conversas.entries()].map(([conversation_id, mensagens]) => {
  mensagens.sort((a, b) => a.quando - b.quando || a.indice - b.indice);
  return {
    conversation_id,
    content: mensagens.map(m => m.texto).join(' '),
    quantidade_mensagens: mensagens.length,
    primeira_mensagem_em: mensagens[0].created_at,
    ultima_mensagem_em: mensagens[mensagens.length - 1].created_at,
    _inicio: mensagens[0].quando,
  };
});

// Conversa que começou primeiro sai primeiro.
resultado.sort((a, b) => a._inicio - b._inicio);

return resultado.map(({ _inicio, ...json }) => ({ json }));
